import React, { useState } from 'react';
import axios from 'axios';
import toast, { Toaster } from 'react-hot-toast';

const RegisterCard = () => {
  const [formData, setFormData] = useState({
    uid: '',
    fullName: '',
    userClass: '',
    role: 'student'
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Adjust URL if your backend runs on a different port or domain
      const response = await axios.post('http://localhost:5000/api/cards/register', formData);
      
      toast.success(response.data.message || 'Card registered successfully!');
      
      // Reset form fields
      setFormData({
        uid: '',
        fullName: '',
        userClass: '',
        role: 'student'
      });
    } catch (err) {
      const errorMsg = err.response?.data?.error || 'Failed to register card. Try again.';
      toast.error(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center px-4">
      <Toaster position="top-right" />
      <div className="max-w-md w-full bg-slate-800 border border-slate-700 rounded-2xl shadow-xl p-8">
        
        <div className="text-center mb-8">
          <h2 className="text-2xl font-bold text-white tracking-wide">Smart Card Registration</h2>
          <p className="text-slate-400 text-sm mt-1">Link an RFID/NFC card to a user profile</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-5">
          {/* Card UID */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-300 mb-2">
              Card UID (Scan or Type)
            </label>
            <input
              type="text"
              name="uid"
              value={formData.uid}
              onChange={handleChange}
              required
              placeholder="e.g. A43F892B"
              className="w-full bg-slate-900 border border-slate-750 text-white rounded-lg px-4 py-3 focus:outline-none focus:border-indigo-500 transition-colors"
            />
          </div>

          {/* Full Name */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-300 mb-2">
              Full Name
            </label>
            <input
              type="text"
              name="fullName"
              value={formData.fullName}
              onChange={handleChange}
              required
              placeholder="e.g. John Doe"
              className="w-full bg-slate-900 border border-slate-750 text-white rounded-lg px-4 py-3 focus:outline-none focus:border-indigo-500 transition-colors"
            />
          </div>

          {/* Class / Department */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-300 mb-2">
              Class / Department
            </label>
            <input
              type="text"
              name="userClass"
              value={formData.userClass}
              onChange={handleChange}
              required
              placeholder="e.g. SS3 Science / Computer Engineering"
              className="w-full bg-slate-900 border border-slate-750 text-white rounded-lg px-4 py-3 focus:outline-none focus:border-indigo-500 transition-colors"
            />
          </div>

          {/* Role Selection */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-300 mb-2">
              Role
            </label>
            <select
              name="role"
              value={formData.role}
              onChange={handleChange}
              className="w-full bg-slate-900 border border-slate-750 text-white rounded-lg px-4 py-3 focus:outline-none focus:border-indigo-500 transition-colors"
            >
              <option value="student">Student</option>
              <option value="staff">Staff</option>
            </select>
          </div>

          {/* Submit Button */}
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-semibold py-3 rounded-lg transition-all duration-200 shadow-lg disabled:opacity-50 mt-2"
          >
            {loading ? 'Registering...' : 'Register Card'}
          </button>
        </form>

      </div>
    </div>
  );
};

export default RegisterCard;
